// Cloudflare Worker — private front door for the financial dashboard.
//
// What this does:
//   1. Requires HTTP Basic Auth before serving anything (401 challenge
//      otherwise) — keeps the dashboard off the public internet even though
//      Cloudflare Workers themselves don't have a private-visibility toggle.
//   2. Serves the dashboard HTML at "/".
//   3. Proxies "/data" server-side to the real Google Apps Script /exec URL.
//      This request never touches a browser, so none of the CORS /
//      anti-abuse redirect issues Google's endpoint has with browser-side
//      fetch()/JSONP apply here — it's a plain server-to-server GET.
//
// SETUP (Cloudflare dashboard, no CLI needed):
//   1. workers.cloudflare.com -> Create Worker -> paste this whole file.
//   2. Settings -> Variables and Secrets -> add:
//        AUTH_USER   (plain text)  e.g. "sean"
//        AUTH_PASS   (encrypt!)    a real password, not a Google password
//        GAS_URL     (plain text)  your Apps Script /exec URL
//   3. Deploy. Your dashboard is now at https://<worker-name>.<subdomain>.workers.dev
//      and will prompt for the username/password you set above.
//
// Re-deploying after editing dashboard.html: re-run build.py to regenerate
// this file's DASHBOARD_HTML constant, then paste the updated worker.js
// back into the Cloudflare dashboard.

const DASHBOARD_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Financial Dashboard \u2014 Sean &amp; Cecilia Barnett</title>\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js\"></script>\n  <style>\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    :root {\n      --bg:#0f1117; --surface:#1a1d27; --surface2:#222636; --border:#2e3248;\n      --text:#e8eaf0; --muted:#7b82a0;\n      --green:#22d3a5; --red:#f87171; --yellow:#fbbf24;\n      --blue:#60a5fa; --purple:#a78bfa; --orange:#fb923c; --accent:#6366f1;\n    }\n    body { font-family:-apple-system,BlinkMacSystemFont,'Inter','Segoe UI',sans-serif; background:var(--bg); color:var(--text); font-size:14px; line-height:1.5; }\n    .page { max-width:1400px; margin:0 auto; padding:24px 20px 60px; }\n    h2 { font-size:13px; font-weight:600; text-transform:uppercase; letter-spacing:.8px; color:var(--muted); margin-bottom:14px; }\n    h3 { font-size:15px; font-weight:600; margin-bottom:10px; }\n    .card { background:var(--surface); border:1px solid var(--border); border-radius:12px; padding:20px; }\n    .kpi-grid  { display:grid; grid-template-columns:repeat(4,1fr); gap:14px; margin-bottom:20px; }\n    .two-col   { display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-bottom:14px; }\n    .wide-left { display:grid; grid-template-columns:2fr 1fr; gap:14px; margin-bottom:14px; }\n    @media(max-width:960px){.kpi-grid{grid-template-columns:repeat(2,1fr)}.two-col,.wide-left{grid-template-columns:1fr}}\n    .kpi { padding:18px 20px; }\n    .kpi-label { font-size:12px; color:var(--muted); text-transform:uppercase; letter-spacing:.6px; margin-bottom:6px; }\n    .kpi-value { font-size:28px; font-weight:700; letter-spacing:-.5px; line-height:1; }\n    .kpi-sub   { font-size:12px; color:var(--muted); margin-top:5px; }\n\n    /* accounts */\n    .acct-section { margin-bottom:14px; }\n    .acct-type-label { font-size:11px; font-weight:600; text-transform:uppercase; letter-spacing:.8px; color:var(--muted); margin-bottom:7px; }\n    .acct-row { display:flex; justify-content:space-between; align-items:center; padding:8px 10px; border-radius:7px; margin-bottom:3px; background:var(--surface2); }\n    .acct-name { font-size:13px; }\n    .acct-name small { color:var(--muted); font-size:11px; display:block; }\n    .acct-bal { font-weight:600; font-size:14px; }\n    .acct-bal.neg { color:var(--red); }\n    .acct-total-row { display:flex; justify-content:space-between; align-items:center; padding:8px 10px; border-radius:7px; margin-top:6px; background:rgba(99,102,241,.1); border:1px solid rgba(99,102,241,.25); }\n    .acct-total-row .lbl { font-size:12px; font-weight:600; color:var(--accent); }\n    .acct-total-row .val { font-size:15px; font-weight:700; }\n\n    /* budget */\n    .budget-group-card { padding:12px 14px; border-radius:8px; background:var(--surface2); }\n    .budget-group-label { font-size:11px; text-transform:uppercase; letter-spacing:.7px; color:var(--muted); margin-bottom:4px; }\n    .budget-summary { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin-bottom:16px; }\n    .progress-bar-wrap { height:5px; background:var(--border); border-radius:99px; margin-top:8px; overflow:hidden; }\n    .progress-bar { height:100%; border-radius:99px; }\n\n    /* budget table */\n    .budget-table { width:100%; border-collapse:collapse; font-size:13px; }\n    .budget-table th { text-align:right; font-size:11px; font-weight:600; color:var(--muted); text-transform:uppercase; letter-spacing:.5px; padding:0 8px 8px; }\n    .budget-table th:first-child { text-align:left; }\n    .budget-table td { padding:5px 8px; border-top:1px solid var(--border); }\n    .budget-table td:not(:first-child) { text-align:right; }\n    .over  { color:var(--red); }\n    .under { color:var(--green); }\n    .mini-bar-wrap { width:50px; height:4px; background:var(--border); border-radius:99px; overflow:hidden; display:inline-block; }\n    .mini-bar { height:100%; border-radius:99px; }\n\n    /* FIRE */\n    .fire-status-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin-bottom:16px; }\n    .fire-loc-card { padding:14px; border-radius:8px; background:var(--surface2); border:1px solid var(--border); cursor:pointer; transition:border-color .2s; }\n    .fire-loc-card.active { border-color:var(--accent); background:rgba(99,102,241,.08); }\n    .fire-loc-name { font-size:12px; font-weight:600; margin-bottom:6px; }\n    .fire-loc-num { font-size:18px; font-weight:700; }\n    .fire-loc-meta { font-size:11px; color:var(--muted); margin-top:3px; }\n    .fire-progress { height:6px; background:var(--border); border-radius:99px; margin-top:10px; overflow:hidden; }\n    .fire-progress-bar { height:100%; border-radius:99px; background:var(--accent); transition:width .4s; }\n\n    /* assumptions */\n    .assumption-grid { display:grid; grid-template-columns:1fr 1fr; gap:16px 24px; }\n    @media(max-width:700px){.assumption-grid{grid-template-columns:1fr}}\n    .assumption-item label { display:flex; justify-content:space-between; align-items:center; font-size:13px; margin-bottom:5px; }\n    .assumption-item label span { font-weight:600; color:var(--accent); }\n    input[type=range] { width:100%; accent-color:var(--accent); cursor:pointer; }\n    select { background:var(--surface2); color:var(--text); border:1px solid var(--border); border-radius:6px; padding:5px 8px; font-size:13px; width:100%; cursor:pointer; }\n\n    /* scenario table */\n    .scenario-table { width:100%; border-collapse:collapse; font-size:13px; }\n    .scenario-table th { text-align:left; font-size:11px; font-weight:600; color:var(--muted); text-transform:uppercase; letter-spacing:.5px; padding:0 10px 8px; }\n    .scenario-table th:not(:first-child) { text-align:right; }\n    .scenario-table td { padding:8px 10px; border-top:1px solid var(--border); }\n    .scenario-table td:not(:first-child) { text-align:right; }\n    .scenario-table tr.highlight td { background:rgba(99,102,241,.08); color:var(--accent); font-weight:600; }\n\n    /* income */\n    .income-row { display:flex; justify-content:space-between; align-items:center; padding:9px 12px; border-radius:7px; margin-bottom:4px; background:var(--surface2); }\n    .income-actual { font-weight:600; color:var(--green); }\n    .income-budget { color:var(--muted); }\n\n    /* tabs */\n    .tabs { display:flex; gap:6px; margin-bottom:16px; }\n    .tab { padding:6px 14px; border-radius:6px; font-size:12px; font-weight:600; cursor:pointer; background:var(--surface2); color:var(--muted); border:1px solid transparent; transition:all .15s; }\n    .tab.active { background:var(--accent); color:#fff; }\n    .tab-panel { display:none; }\n    .tab-panel.active { display:block; }\n\n    /* pill */\n    .pill { display:inline-flex; align-items:center; gap:4px; font-size:11px; font-weight:600; padding:3px 8px; border-radius:99px; }\n    .pill-green { background:rgba(34,211,165,.1); color:var(--green); }\n    .pill-red   { background:rgba(248,113,113,.1); color:var(--red); }\n    .pill-yellow{ background:rgba(251,191,36,.1); color:var(--yellow); }\n\n    /* live status */\n    #live-status { font-size:11px; color:var(--muted); }\n    #live-status.live  { color:var(--green); }\n    #live-status.error { color:var(--red); }\n\n    .note { font-size:11px; color:var(--muted); margin-top:10px; line-height:1.6; }\n    .section-gap { margin-bottom:14px; }\n  </style>\n</head>\n<body>\n<div class=\"page\">\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 HEADER \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div style=\"display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:28px;flex-wrap:wrap;gap:12px\">\n  <div>\n    <div style=\"font-size:22px;font-weight:700;letter-spacing:-.3px\">Financial Dashboard</div>\n    <div style=\"color:var(--muted);font-size:13px;margin-top:4px\">Sean &amp; Cecilia Barnett &nbsp;\u00b7&nbsp; Data via Tiller / Google Sheets</div>\n  </div>\n  <div style=\"text-align:right\">\n    <div id=\"live-status\">\u2b2d loading\u2026</div>\n    <div style=\"font-size:11px;color:var(--muted);margin-top:3px\" id=\"last-updated\"></div>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 KPI STRIP \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"kpi-grid\">\n  <div class=\"card kpi\">\n    <div class=\"kpi-label\">Net Worth</div>\n    <div class=\"kpi-value\" style=\"color:var(--green)\" id=\"kpi-nw\">\u2014</div>\n    <div class=\"kpi-sub\" id=\"kpi-nw-sub\"></div>\n  </div>\n  <div class=\"card kpi\">\n    <div class=\"kpi-label\">FIRE Assets</div>\n    <div class=\"kpi-value\" id=\"kpi-fire-assets\">\u2014</div>\n    <div class=\"kpi-sub\" id=\"kpi-fire-sub\"><span class=\"pill pill-yellow\">Early Stage</span></div>\n  </div>\n  <div class=\"card kpi\">\n    <div class=\"kpi-label\">Monthly Cash Flow</div>\n    <div class=\"kpi-value\" id=\"kpi-cf\">\u2014</div>\n    <div class=\"kpi-sub\" id=\"kpi-cf-sub\"></div>\n  </div>\n  <div class=\"card kpi\">\n    <div class=\"kpi-label\">Time to FIRE</div>\n    <div class=\"kpi-value\" id=\"kpi-years\">\u2014</div>\n    <div class=\"kpi-sub\" id=\"kpi-fire-year\"></div>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 ACCOUNTS + NET WORTH CHART \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"wide-left section-gap\">\n  <div class=\"card\" id=\"accounts-card\">\n    <h2>Accounts</h2>\n    <div id=\"accounts-body\">\n      <div style=\"color:var(--muted);font-size:13px\">Loading accounts\u2026</div>\n    </div>\n  </div>\n  <div class=\"card\" style=\"display:flex;flex-direction:column\">\n    <h2>Net Worth \u2014 12 Month History</h2>\n    <div style=\"flex:1;min-height:320px;position:relative\"><canvas id=\"nwChart\"></canvas></div>\n    <p class=\"note\">Tiller-tracked accounts: checking + savings + investment \u2212 credit card.</p>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 PORTFOLIO \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"two-col section-gap\">\n  <div class=\"card\">\n    <h2>Portfolio Mix (Investment Accounts)</h2>\n    <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:center\">\n      <div style=\"max-width:220px;margin:0 auto\"><canvas id=\"portfolioDonut\"></canvas></div>\n      <div id=\"portfolioLegend\"></div>\n    </div>\n  </div>\n  <div class=\"card\">\n    <h2>Investment Growth \u2014 12 Months</h2>\n    <div style=\"min-height:220px;position:relative\"><canvas id=\"investChart\"></canvas></div>\n    <p class=\"note\" id=\"invest-note\"></p>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 MONTHLY BUDGET \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"card section-gap\">\n  <div style=\"display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px\">\n    <h2 style=\"margin:0\">Monthly Budget</h2>\n    <span style=\"font-size:13px;color:var(--muted)\" id=\"budget-period\"></span>\n  </div>\n  <div id=\"budget-income-section\"></div>\n  <div class=\"budget-summary\" id=\"budget-summary-cards\"></div>\n  <div class=\"tabs\" id=\"budget-tabs\"></div>\n  <div id=\"budget-tab-panels\"></div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 FIRE PROJECTIONS \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"card section-gap\">\n  <h2>FIRE Projections</h2>\n  <div class=\"fire-status-grid\" id=\"fireLocCards\"></div>\n  <div style=\"min-height:320px;position:relative;margin-bottom:12px\"><canvas id=\"fireChart\"></canvas></div>\n  <p class=\"note\">\n    Real (inflation-adjusted) returns. Anchor year: <span id=\"note-anchor\">2026</span>.\n    Real return = nominal \u2212 inflation.\n    FIRE # = baseline spending \u00d7 retirement adj \u00d7 geographic adj \u00f7 SWR.\n    <strong id=\"note-fire-basis\" style=\"color:var(--yellow)\"></strong>\n  </p>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 ASSUMPTIONS PIVOT \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"two-col section-gap\">\n  <div class=\"card\">\n    <h2>Assumptions \u2014 Pivot Model</h2>\n    <div class=\"assumption-grid\">\n      <div class=\"assumption-item\">\n        <label>Monthly Investment <span id=\"lbl-monthly\">$2,800</span></label>\n        <input type=\"range\" id=\"sl-monthly\" min=\"500\" max=\"10000\" step=\"100\" value=\"2800\" oninput=\"updateModel()\">\n      </div>\n      <div class=\"assumption-item\">\n        <label>Annual Bonus Invested <span id=\"lbl-bonus\">$2,000</span></label>\n        <input type=\"range\" id=\"sl-bonus\" min=\"0\" max=\"20000\" step=\"500\" value=\"2000\" oninput=\"updateModel()\">\n      </div>\n      <div class=\"assumption-item\">\n        <label>Expected Nominal Return <span id=\"lbl-return\">10.0%</span></label>\n        <input type=\"range\" id=\"sl-return\" min=\"4\" max=\"15\" step=\"0.5\" value=\"10\" oninput=\"updateModel()\">\n      </div>\n      <div class=\"assumption-item\">\n        <label>Expected Inflation <span id=\"lbl-inflation\">2.5%</span></label>\n        <input type=\"range\" id=\"sl-inflation\" min=\"1\" max=\"6\" step=\"0.5\" value=\"2.5\" oninput=\"updateModel()\">\n      </div>\n      <div class=\"assumption-item\">\n        <label>Annual Spending (Baseline) <span id=\"lbl-spending\">$75,000</span></label>\n        <input type=\"range\" id=\"sl-spending\" min=\"30000\" max=\"200000\" step=\"1000\" value=\"75000\" oninput=\"updateModel()\">\n      </div>\n      <div class=\"assumption-item\">\n        <label>Retirement Adjustment <span id=\"lbl-retadj\">85%</span></label>\n        <input type=\"range\" id=\"sl-retadj\" min=\"50\" max=\"100\" step=\"5\" value=\"85\" oninput=\"updateModel()\">\n      </div>\n      <div class=\"assumption-item\">\n        <label>Safe Withdrawal Rate <span id=\"lbl-swr\">4.50%</span></label>\n        <input type=\"range\" id=\"sl-swr\" min=\"3\" max=\"5.5\" step=\"0.25\" value=\"4.5\" oninput=\"updateModel()\">\n      </div>\n      <div class=\"assumption-item\">\n        <label>Geographic Scenario <span id=\"lbl-geo\">Mexico Full-Time</span></label>\n        <select id=\"sel-geo\" onchange=\"updateModel()\">\n          <option value=\"1.0\">\ud83c\uddfa\ud83c\uddf8 US Full-Time (100%)</option>\n          <option value=\"0.7\">\ud83c\udf2e Mexico Part-Time (70%)</option>\n          <option value=\"0.55\" selected>\ud83c\udf34 Mexico Full-Time (55%)</option>\n        </select>\n      </div>\n    </div>\n    <div style=\"margin-top:20px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px\">\n      <div style=\"padding:12px;background:var(--surface2);border-radius:8px;text-align:center\">\n        <div style=\"font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.6px;margin-bottom:4px\">FIRE Number</div>\n        <div style=\"font-size:18px;font-weight:700;color:var(--accent)\" id=\"out-fire-num\">\u2014</div>\n      </div>\n      <div style=\"padding:12px;background:var(--surface2);border-radius:8px;text-align:center\">\n        <div style=\"font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.6px;margin-bottom:4px\">Years to FIRE</div>\n        <div style=\"font-size:18px;font-weight:700\" id=\"out-years\">\u2014</div>\n      </div>\n      <div style=\"padding:12px;background:var(--surface2);border-radius:8px;text-align:center\">\n        <div style=\"font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.6px;margin-bottom:4px\">Target Year</div>\n        <div style=\"font-size:18px;font-weight:700\" id=\"out-year\">\u2014</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>Investment Scenario Sensitivity</h2>\n    <table class=\"scenario-table\"><thead><tr><th>Monthly Invest</th><th>Annual Total</th><th>Years</th><th>Year</th><th>Age</th></tr></thead>\n      <tbody id=\"scenario-tbody\"></tbody></table>\n    <div style=\"margin-top:20px\">\n      <h3>SWR Sensitivity</h3>\n      <table class=\"scenario-table\" style=\"margin-top:10px\"><thead><tr><th>Scenario</th><th>SWR</th><th>FIRE #</th><th>Years</th></tr></thead>\n        <tbody id=\"swr-tbody\"></tbody></table>\n    </div>\n    <div style=\"margin-top:20px\">\n      <h3>Location Comparison</h3>\n      <table class=\"scenario-table\" style=\"margin-top:10px\"><thead><tr><th>Location</th><th>Annual Need</th><th>FIRE #</th><th>Years</th></tr></thead>\n        <tbody id=\"loc-tbody\"></tbody></table>\n    </div>\n  </div>\n</div>\n\n<!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 BUDGET CHART \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n<div class=\"card section-gap\">\n  <h2>Budget vs Actual by Group</h2>\n  <div style=\"min-height:240px;position:relative\"><canvas id=\"budgetGroupChart\"></canvas></div>\n</div>\n\n</div><!-- /page -->\n<script>\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// CONFIG \u2014 Google Apps Script /exec URL\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nvar CONFIG = {\n  // Relative endpoint served by the Cloudflare Worker that fronts this page.\n  // The Worker holds the real Google Apps Script /exec URL server-side and\n  // proxies it here \u2014 see /cloudflare-worker/worker.js.\n  GAS_URL: '/data',\n  BIRTH_YEAR: 1985,\n  START_YEAR: 2026,\n};\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// FALLBACK STATIC DATA\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nvar STATIC = {\n  balances: {\n    checking: [\n      { name: 'CeciliaSean (xxxx8907)',  updated: 'today',       balance: 1939 },\n      { name: 'LUA BIZ CHK (xxxx6169)', updated: 'today',       balance: 2100 },\n    ],\n    savings: [\n      { name: 'Money Market Savings (xxxx5027)',       updated: 'today',     balance: 14143 },\n      { name: 'IBKR Brokerage Savings / Taxable (xxxx5887)', updated: '1 day ago', balance: 5759 },\n      { name: 'Lively HSA \u2014 Sean (xx5471)',             updated: '146 days ago', balance: 3000 },\n    ],\n    investment: [\n      { name: 'Cecilia Roth IRA (IBKR xxxx9267)',              updated: '1 day ago',  balance: 17862 },\n      { name: 'Vanguard Roth IRA \u2014 Sean (xxxx3356)',            updated: 'today',      balance: 16815 },\n      { name: 'Gulf Winds 401(k) \u2014 Cecilia (xxxx2801)',         updated: 'today',      balance: 12450 },\n      { name: 'TADPULL 401k \u2014 Sean (Ascensus xxxx1721)',        updated: '1 day ago',  balance: 13531 },\n      { name: 'Cece HSA (x1722)',                               updated: '18 days ago',balance:  8051 },\n      { name: 'HSA \u2014 Sean (Schwab xxxxx682)',                   updated: '1 day ago',  balance:  1846 },\n    ],\n    credit: [\n      { name: 'Chase Sapphire SB (xxxx5386)', updated: '1 day ago', balance: 4204 },\n    ],\n  },\n  history: {\n    checking:    [155, 1123, 514, 151, 4853, 1382, 835, 313, 9176, 1039, 7603, 4039],\n    investment:  [2582, 2759, 5008, 5516, 6711, 12588, 21902, 28214, 32821, 41524, 54061, 70554],\n    savings:     [0, 0, 38, 5485, 7163, 9527, 8905, 8711, 15660, 19534, 22229, 22902],\n    liabilities: [707, 1930, 146, 106, 303, 1482, 2254, 665, 2364, 808, 2861, 4204],\n  },\n  assumptions: {\n    nominalReturn: 0.10, inflation: 0.025, realReturn: 0.073,\n    swr: 0.045, annualSpending: 75000, retirementAdj: 0.85, geoAdj: 0.55,\n    totalMonthly: 2800, bonusAmt: 2000, annualTotal: 35600, inflationAnchor: 2026,\n  },\n  budget: {\n    period: 'April 2026',\n    groups: [\n      { name: 'Income', type: 'income', budget: 9358.33, actual: 9387.41,\n        categories: [\n          { name: 'TadPull',         budget: 5574.53, actual: 5592.73 },\n          { name: 'Gulf Winds',      budget: 3783.80, actual: 3794.68 },\n          { name: 'Dividends, Misc', budget: 0,       actual: 0 },\n        ]\n      },\n      { name: 'Fixed Bills', type: 'expense', budget: 4244.14, actual: 4611.32,\n        categories: [\n          { name: 'Mortgage',        budget: 1461.06, actual: 1374.72 },\n          { name: 'Groceries',       budget: 850,     actual:  819.82 },\n          { name: 'Pet Care',        budget: 225,     actual:  553.91 },\n          { name: 'Tundra Payment',  budget: 500,     actual:  500.00 },\n          { name: 'Internet/Mobile', budget: 218.08,  actual:  259.16 },\n          { name: 'Gym/Yoga',        budget: 161,     actual:  157.88 },\n          { name: 'Car Gas (Exxon)', budget: 250,     actual:  111.32 },\n          { name: 'Car Maintenance', budget: 90,      actual:  155.72 },\n          { name: 'Electric',        budget: 150,     actual:  102.93 },\n          { name: 'Medical Care',    budget: 0,       actual:  199.61 },\n          { name: 'Lawncare',        budget: 90,      actual:  130.00 },\n          { name: 'Rooms2Go',        budget: 100,     actual:  100.00 },\n          { name: 'Water',           budget: 99,      actual:   98.46 },\n          { name: 'Gas',             budget: 50,      actual:   47.79 },\n        ]\n      },\n      { name: 'Guilt Free Spend', type: 'expense', budget: 2610.06, actual: 3898.30,\n        categories: [\n          { name: 'Home Improvements', budget: 200,    actual: 1510.70 },\n          { name: 'Eating Out',         budget: 500,   actual:  633.28 },\n          { name: 'Entertainment',      budget: 300,   actual:  388.69 },\n          { name: 'Gift',               budget: 250,   actual:  307.36 },\n          { name: 'Shopping',           budget: 0,     actual:  356.33 },\n          { name: 'Personal Care',      budget: 250,   actual:  274.53 },\n          { name: 'Personal Dev',       budget: 200,   actual:  227.78 },\n          { name: 'Subscription',       budget: 135.06,actual:  187.24 },\n          { name: 'Travel',             budget: 750,   actual:   10.00 },\n          { name: 'Incidentals',        budget: 25,    actual:    2.39 },\n        ]\n      },\n      { name: 'Save & Invest', type: 'expense', budget: 3250, actual: 3050,\n        categories: [\n          { name: 'Roth Cece',   budget: 500,  actual: 2250 },\n          { name: 'HSA Sean',    budget: 250,  actual:  800 },\n          { name: 'Money Saved', budget: 1000, actual:    0 },\n          { name: 'Roth Sean',   budget: 1500, actual:    0 },\n        ]\n      },\n    ]\n  },\n};\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// MATH HELPERS\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nvar fmt  = function(n, d) { d = d || 0; return '$' + (+n).toLocaleString('en-US', {minimumFractionDigits:d, maximumFractionDigits:d}); };\nvar fmtS = function(n, d) { d = d || 0; return (n < 0 ? '\u2212' : '+') + fmt(Math.abs(n), d); };\n\nfunction realReturn(nom, inf) { return (1 + nom) / (1 + inf) - 1; }\nfunction fireNumber(spending, retAdj, geoAdj, swr) { return (spending * retAdj * geoAdj) / swr; }\n\nfunction yearsToFire(assets, annualInv, rr, fireNum) {\n  var bal = assets, y = 0;\n  while (bal < fireNum && y < 100) { bal = bal * (1 + rr) + annualInv; y++; }\n  return y;\n}\n\nfunction computeProjections(assets, annualInv, rr, fireNum) {\n  var rows = [];\n  var bal = assets;\n  for (var y = 0; y <= 28; y++) {\n    rows.push({ year: CONFIG.START_YEAR + y, balance: Math.round(bal), ratio: bal / fireNum, gap: Math.max(0, fireNum - bal) });\n    bal = bal * (1 + rr) + annualInv;\n  }\n  return rows;\n}\n\nfunction sumBalances(accts) { return accts.reduce(function(s, a) { return s + a.balance; }, 0); }\n\nfunction netWorthFromData(d) {\n  var assets = sumBalances(d.checking) + sumBalances(d.savings) + sumBalances(d.investment);\n  var liab   = sumBalances(d.credit);\n  return assets - liab;\n}\n\nfunction fireAssetsFromData(d) {\n  return sumBalances(d.investment) + sumBalances(d.savings);\n}\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// CHART SETUP\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nChart.defaults.color = '#7b82a0';\nChart.defaults.borderColor = '#2e3248';\nChart.defaults.font.family = \"-apple-system,'Inter','Segoe UI',sans-serif\";\n\nvar MONTHS_LABELS = ['May 25','Jun 25','Jul 25','Aug 25','Sep 25','Oct 25','Nov 25','Dec 25','Jan 26','Feb 26','Mar 26','Apr 26'];\n\nvar nwChart, portfolioChart, investChart, fireChart, budgetChart;\n\nfunction initCharts() {\n  nwChart = new Chart(document.getElementById('nwChart').getContext('2d'), {\n    type: 'line',\n    data: { labels: MONTHS_LABELS, datasets: [] },\n    options: { responsive:true, maintainAspectRatio:false, interaction:{mode:'index',intersect:false},\n      plugins:{ legend:{position:'bottom',labels:{boxWidth:12,padding:16}},\n        tooltip:{callbacks:{label:function(ctx){return ' '+ctx.dataset.label+': '+fmt(ctx.raw)}}} },\n      scales:{ y:{ticks:{callback:function(v){return fmt(v)}}, grid:{color:'#2e3248'}}, x:{grid:{display:false}} } }\n  });\n\n  portfolioChart = new Chart(document.getElementById('portfolioDonut').getContext('2d'), {\n    type: 'doughnut',\n    data: { labels: [], datasets: [{ data:[], backgroundColor:[], borderColor:'#1a1d27', borderWidth:3, hoverOffset:6 }] },\n    options: { responsive:true, maintainAspectRatio:true, cutout:'65%',\n      plugins:{ legend:{display:false}, tooltip:{callbacks:{label:function(ctx){return ' '+ctx.label+': '+fmt(ctx.raw)}}} } }\n  });\n\n  investChart = new Chart(document.getElementById('investChart').getContext('2d'), {\n    type: 'line',\n    data: { labels: MONTHS_LABELS, datasets: [] },\n    options: { responsive:true, maintainAspectRatio:false,\n      plugins:{ legend:{display:false}, tooltip:{callbacks:{label:function(ctx){return ' Investment: '+fmt(ctx.raw)}}} },\n      scales:{ y:{ticks:{callback:function(v){return fmt(v)}}, grid:{color:'#2e3248'}}, x:{grid:{display:false}} } }\n  });\n\n  fireChart = new Chart(document.getElementById('fireChart').getContext('2d'), {\n    type: 'line',\n    data: { labels: [], datasets: [] },\n    options: { responsive:true, maintainAspectRatio:false, interaction:{mode:'index',intersect:false},\n      plugins:{ legend:{position:'bottom',labels:{boxWidth:12,padding:16}},\n        tooltip:{callbacks:{label:function(ctx){return ' '+ctx.dataset.label+': '+fmt(ctx.raw)}}} },\n      scales:{ y:{ticks:{callback:function(v){return fmt(v)}}, grid:{color:'#2e3248'}}, x:{grid:{display:false}} } }\n  });\n\n  budgetChart = new Chart(document.getElementById('budgetGroupChart').getContext('2d'), {\n    type: 'bar',\n    data: { labels: [], datasets: [] },\n    options: { responsive:true, maintainAspectRatio:false,\n      plugins:{ legend:{position:'bottom',labels:{boxWidth:12,padding:16}},\n        tooltip:{callbacks:{label:function(ctx){return ' '+ctx.dataset.label+': '+fmt(ctx.raw,2)}}} },\n      scales:{ y:{ticks:{callback:function(v){return fmt(v)}}, grid:{color:'#2e3248'}}, x:{grid:{display:false}} } }\n  });\n}\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// RENDER FUNCTIONS\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nvar PALETTE = ['#6366f1','#22d3a5','#60a5fa','#a78bfa','#fbbf24','#fb923c','#f472b6','#34d399'];\n\nfunction renderAccounts(balances) {\n  var sections = [\n    { key:'checking',   label:'Checking' },\n    { key:'investment', label:'Investment' },\n    { key:'savings',    label:'Savings' },\n    { key:'credit',     label:'Credit Card (Liability)', neg:true },\n  ];\n  var html = '';\n  for (var i = 0; i < sections.length; i++) {\n    var section = sections[i];\n    var list = balances[section.key] || [];\n    if (!list.length) continue;\n    var total = list.reduce(function(s,a){return s+a.balance},0);\n    html += '<div class=\"acct-section\"><div class=\"acct-type-label\">'+section.label+'</div>';\n    for (var j = 0; j < list.length; j++) {\n      var a = list[j];\n      html += '<div class=\"acct-row\"><div class=\"acct-name\">'+a.name+(a.updated?'<small>'+a.updated+'</small>':'')+'</div><div class=\"acct-bal'+(section.neg?' neg':'') + '\">'+(section.neg?'\u2212':'')+fmt(a.balance)+'</div></div>';\n    }\n    html += '<div class=\"acct-total-row\"><span class=\"lbl\">'+section.label+' Total</span><span class=\"val'+(section.neg?' neg':'')+'>'+(section.neg?'\u2212':'')+fmt(total)+'</span></div></div>';\n  }\n\n  var nw = netWorthFromData(balances);\n  var fireAssets = fireAssetsFromData(balances);\n  html += '<div style=\"margin-top:14px;padding:12px 14px;background:rgba(34,211,165,.06);border:1px solid rgba(34,211,165,.2);border-radius:8px;display:flex;justify-content:space-between;align-items:center\"><div><div style=\"font-size:13px;font-weight:600\">Tracked Net Worth</div><div style=\"font-size:11px;color:var(--muted);margin-top:2px\">All assets \u2212 liabilities</div></div><span style=\"font-size:20px;font-weight:700;color:var(--green)\">'+fmt(nw)+'</span></div>';\n  html += '<div style=\"margin-top:8px;padding:10px 14px;background:rgba(99,102,241,.06);border:1px solid rgba(99,102,241,.2);border-radius:8px;display:flex;justify-content:space-between;align-items:center\"><div><div style=\"font-size:13px;font-weight:600\">FIRE Assets</div><div style=\"font-size:11px;color:var(--muted);margin-top:2px\">Investment + savings accounts</div></div><span style=\"font-size:18px;font-weight:700;color:var(--accent)\">'+fmt(fireAssets)+'</span></div>';\n\n  document.getElementById('accounts-body').innerHTML = html;\n  return { nw: nw, fireAssets: fireAssets };\n}\n\nfunction renderHistory(history) {\n  // Apps Script supplies the real trailing-12-month labels; MONTHS_LABELS is\n  // only a fallback for the static demo data. Any series can come back null\n  // if the Balance History sheet is missing, so default those to zeros\n  // rather than letting the charts throw.\n  var labels = (history && history.labels) || MONTHS_LABELS;\n  var zeros = labels.map(function() { return 0; });\n  var checking    = history.checking    || zeros;\n  var investment  = history.investment  || zeros;\n  var savings     = history.savings     || zeros;\n  var liabilities = history.liabilities || zeros;\n\n  nwChart.data.labels = labels;\n  investChart.data.labels = labels;\n\n  var nwHist = labels.map(function(_,i) { return (checking[i]||0) + (investment[i]||0) + (savings[i]||0) - (liabilities[i]||0); });\n  nwChart.data.datasets = [\n    { label:'Net Worth', data:nwHist, borderColor:'#22d3a5', backgroundColor:'rgba(34,211,165,.08)', fill:true, tension:0.4, pointRadius:4, pointBackgroundColor:'#22d3a5' },\n    { label:'Investment', data:investment, borderColor:'#6366f1', backgroundColor:'transparent', tension:0.4, pointRadius:3, borderDash:[4,3] },\n  ];\n  nwChart.update();\n\n  investChart.data.datasets = [{\n    label:'Investment Total', data:investment,\n    borderColor:'#6366f1', backgroundColor:'rgba(99,102,241,.1)', fill:true, tension:0.4, pointRadius:4, pointBackgroundColor:'#6366f1',\n  }];\n  investChart.update();\n\n  var first = investment[0], last = investment[investment.length-1];\n  document.getElementById('invest-note').textContent = first\n    ? 'Investment accounts only. '+labels[0]+': '+fmt(first)+' \u2192 '+labels[labels.length-1]+': '+fmt(last)+' ('+((last/first-1)*100).toFixed(0)+'% growth over 12 months)'\n    : 'No 12-month history found in the Balance History sheet.';\n\n  return nwHist;\n}\n\nfunction renderPortfolio(investments) {\n  portfolioChart.data.labels = investments.map(function(a){return a.name});\n  portfolioChart.data.datasets[0].data = investments.map(function(a){return a.balance});\n  portfolioChart.data.datasets[0].backgroundColor = investments.map(function(_,i){return PALETTE[i%PALETTE.length]});\n  portfolioChart.update();\n\n  var total = investments.reduce(function(s,a){return s+a.balance},0);\n  var legendHtml = '';\n  for (var i = 0; i < investments.length; i++) {\n    var a = investments[i];\n    legendHtml += '<div style=\"display:flex;align-items:center;gap:7px;margin-bottom:8px\"><div style=\"width:10px;height:10px;border-radius:3px;background:'+PALETTE[i%PALETTE.length]+';flex-shrink:0\"></div><div><div style=\"font-size:12px;line-height:1.3\">'+a.name+'</div><div style=\"font-size:12px;font-weight:600\">'+fmt(a.balance)+' <span style=\"color:var(--muted);font-weight:400;font-size:11px\">'+(a.balance/total*100).toFixed(1)+'%</span></div></div></div>';\n  }\n  document.getElementById('portfolioLegend').innerHTML = legendHtml;\n}\n\nfunction renderBudget(budget) {\n  document.getElementById('budget-period').textContent = budget.period || '';\n\n  var income = null, expenses = [];\n  for (var i = 0; i < budget.groups.length; i++) {\n    var g = budget.groups[i];\n    if (g.type === 'income') income = g;\n    else expenses.push(g);\n  }\n\n  if (income) {\n    var html = '<div style=\"margin-bottom:16px\"><h3 style=\"font-size:12px;text-transform:uppercase;letter-spacing:.7px;color:var(--muted);margin-bottom:8px\">Income</h3>';\n    for (var j = 0; j < income.categories.length; j++) {\n      var c = income.categories[j];\n      if (c.actual > 0 || c.budget > 0) {\n        var v = c.actual - c.budget;\n        html += '<div class=\"income-row\"><span>'+c.name+'</span><div style=\"display:flex;gap:14px;font-size:13px\"><span class=\"income-budget\">Budget '+fmt(c.budget)+'</span><span class=\"income-actual\">'+fmt(c.actual)+' <span class=\"pill '+(v>=0?'pill-green':'pill-red')+'\">'+(v>=0?'+':'')+fmt(v)+'</span></span></div></div>';\n      }\n    }\n    var tv = income.actual - income.budget;\n    html += '<div class=\"income-row\" style=\"background:rgba(99,102,241,.07);border:1px solid rgba(99,102,241,.2)\"><span style=\"font-weight:700\">Total Income</span><div style=\"display:flex;gap:14px;font-size:13px\"><span class=\"income-budget\">Budget '+fmt(income.budget)+'</span><span class=\"income-actual\" style=\"font-size:15px;font-weight:700\">'+fmt(income.actual)+' <span class=\"pill '+(tv>=0?'pill-green':'pill-red')+'\">'+(tv>=0?'+':'')+fmt(tv)+'</span></span></div></div></div>';\n    document.getElementById('budget-income-section').innerHTML = html;\n  }\n\n  var summaryHtml = '';\n  for (var i = 0; i < expenses.length; i++) {\n    var g = expenses[i];\n    var over = g.actual > g.budget;\n    var pct = g.budget>0 ? Math.min(g.actual/g.budget,1.5)*100 : 100;\n    var v = g.actual - g.budget;\n    summaryHtml += '<div class=\"budget-group-card\"><div class=\"budget-group-label\">'+g.name+'</div><div style=\"display:flex;gap:10px;align-items:baseline\"><span style=\"font-size:20px;font-weight:700;color:'+(over?'var(--red)':'var(--green)')+'\">'+fmt(g.actual)+'</span><span style=\"font-size:12px;color:var(--muted)\">/ '+fmt(g.budget)+' budget</span></div><div class=\"progress-bar-wrap\"><div class=\"progress-bar\" style=\"width:'+Math.min(pct,100)+'%;background:'+(over?'var(--red)':'var(--green)')+'\"></div></div><div style=\"font-size:11px;margin-top:4px;color:'+(over?'var(--red)':'var(--green)')+'\">\u2212'+fmt(Math.abs(v))+' '+(over?'over':'under')+' budget</div></div>';\n  }\n  document.getElementById('budget-summary-cards').innerHTML = summaryHtml;\n\n  var tabsEl = document.getElementById('budget-tabs');\n  var panelsEl = document.getElementById('budget-tab-panels');\n  tabsEl.innerHTML = '';\n  panelsEl.innerHTML = '';\n\n  for (var i = 0; i < expenses.length; i++) {\n    (function(idx) {\n      var g = expenses[idx];\n      var id = 'btab-' + idx;\n      var tab = document.createElement('div');\n      tab.className = 'tab' + (idx===0?' active':'');\n      tab.textContent = g.name;\n      tab.onclick = function() {\n        var tabs = document.querySelectorAll('.tab');\n        for (var k = 0; k < tabs.length; k++) tabs[k].classList.remove('active');\n        var panels = document.querySelectorAll('.tab-panel');\n        for (var k = 0; k < panels.length; k++) panels[k].classList.remove('active');\n        tab.classList.add('active');\n        document.getElementById(id).classList.add('active');\n      };\n      tabsEl.appendChild(tab);\n\n      var panel = document.createElement('div');\n      panel.id = id;\n      panel.className = 'tab-panel' + (idx===0?' active':'');\n      var rows = '';\n      for (var j = 0; j < g.categories.length; j++) {\n        var cat = g.categories[j];\n        var cv = cat.actual - cat.budget;\n        var cpct = cat.budget>0 ? Math.min(cat.actual/cat.budget,1.5) : 1;\n        var col = cv > 0 ? '#f87171' : '#22d3a5';\n        rows += '<tr><td>'+cat.name+'</td><td>'+(cat.budget>0?fmt(cat.budget,2):'\u2014')+'</td><td>'+fmt(cat.actual,2)+'</td><td class=\"'+(cv>0?'over':'under')+'\">'+(cv>0?'+':'')+fmt(cv,2)+'</td><td style=\"width:70px;text-align:right;padding:5px 8px\"><div class=\"mini-bar-wrap\"><div class=\"mini-bar\" style=\"width:'+Math.min(cpct*100,100)+'%;background:'+col+'\"></div></div></td></tr>';\n      }\n      panel.innerHTML = '<table class=\"budget-table\"><thead><tr><th>Category</th><th>Budget</th><th>Actual</th><th>Variance</th><th></th></tr></thead><tbody>'+rows+'</tbody></table>';\n      panelsEl.appendChild(panel);\n    })(i);\n  }\n\n  var expLabels = expenses.map(function(g){return g.name}).concat(['Total Income']);\n  var expBudgets = expenses.map(function(g){return g.budget}).concat([income?income.budget:0]);\n  var expActuals = expenses.map(function(g){return g.actual}).concat([income?income.actual:0]);\n  var actColors = expenses.map(function(g){return g.actual>g.budget?'rgba(248,113,113,.6)':'rgba(34,211,165,.5)'}).concat(['rgba(34,211,165,.5)']);\n  var brdColors = expenses.map(function(g){return g.actual>g.budget?'#f87171':'#22d3a5'}).concat(['#22d3a5']);\n\n  budgetChart.data.labels = expLabels;\n  budgetChart.data.datasets = [\n    { label:'Budget', data:expBudgets, backgroundColor:'rgba(99,102,241,.35)', borderColor:'#6366f1', borderWidth:1, borderRadius:4 },\n    { label:'Actual', data:expActuals, backgroundColor:actColors, borderColor:brdColors, borderWidth:1, borderRadius:4 },\n  ];\n  budgetChart.update();\n\n  if (income) {\n    var totalExpenses = expenses.reduce(function(s,g){return s+g.actual},0);\n    var cf = income.actual - totalExpenses;\n    document.getElementById('kpi-cf').textContent = (cf<0?'\u2212':'+')+fmt(Math.abs(cf));\n    document.getElementById('kpi-cf').style.color = cf<0?'var(--red)':'var(--green)';\n    document.getElementById('kpi-cf-sub').textContent = 'Income '+fmt(income.actual)+' \u00b7 Spend '+fmt(totalExpenses);\n  }\n}\n\nvar GEO_OPTS = [\n  { label:'\ud83c\uddfa\ud83c\uddf8 US Full-Time',    geo:1.0 },\n  { label:'\ud83c\udf2e Mexico Part-Time', geo:0.7 },\n  { label:'\ud83c\udf34 Mexico Full-Time', geo:0.55 },\n];\nvar GEO_NAMES = { '1.0':'US Full-Time', '0.7':'Mexico Part-Time', '0.55':'Mexico Full-Time' };\n\nfunction renderFireCards(fireAssets, assumptions) {\n  var rr = realReturn(assumptions.nominalReturn, assumptions.inflation);\n  var annualInv = assumptions.totalMonthly * 12 + assumptions.bonusAmt;\n  var spending  = assumptions.annualSpending;\n  var retAdj    = assumptions.retirementAdj;\n  var swr       = assumptions.swr;\n\n  var el = document.getElementById('fireLocCards');\n  var html = '';\n  for (var i = 0; i < GEO_OPTS.length; i++) {\n    var opt = GEO_OPTS[i];\n    var fn  = fireNumber(spending, retAdj, opt.geo, swr);\n    var yrs = yearsToFire(fireAssets, annualInv, rr, fn);\n    var ratio = fireAssets / fn;\n    var isActive = Math.abs(opt.geo - assumptions.geoAdj) < 0.01;\n    html += '<div class=\"fire-loc-card'+(isActive?' active':'')+'\" data-geo=\"'+opt.geo+'\" onclick=\"selectGeo(this,'+opt.geo+')\"><div class=\"fire-loc-name\">'+opt.label+'</div><div class=\"fire-loc-num\">'+fmt(Math.round(fn))+'</div><div class=\"fire-loc-meta\">'+(ratio*100).toFixed(1)+'% funded \u00b7 '+yrs.toFixed(1)+' yrs</div><div class=\"fire-progress\"><div class=\"fire-progress-bar\" style=\"width:'+Math.min(ratio*100,100)+'%\"></div></div></div>';\n  }\n  el.innerHTML = html;\n}\n\nfunction selectGeo(el, val) {\n  var cards = document.querySelectorAll('.fire-loc-card');\n  for (var i = 0; i < cards.length; i++) cards[i].classList.remove('active');\n  el.classList.add('active');\n  document.getElementById('sel-geo').value = String(val);\n  updateModel();\n}\n\nvar _fireAssets = 0;\n\nfunction updateModel() {\n  var monthly   = +document.getElementById('sl-monthly').value;\n  var bonus     = +document.getElementById('sl-bonus').value;\n  var nomRet    = +document.getElementById('sl-return').value / 100;\n  var inflation = +document.getElementById('sl-inflation').value / 100;\n  var spending  = +document.getElementById('sl-spending').value;\n  var retAdj    = +document.getElementById('sl-retadj').value / 100;\n  var swr       = +document.getElementById('sl-swr').value / 100;\n  var geo       = +document.getElementById('sel-geo').value;\n\n  document.getElementById('lbl-monthly').textContent   = fmt(monthly);\n  document.getElementById('lbl-bonus').textContent     = fmt(bonus);\n  document.getElementById('lbl-return').textContent    = (nomRet*100).toFixed(1)+'%';\n  document.getElementById('lbl-inflation').textContent = (inflation*100).toFixed(1)+'%';\n  document.getElementById('lbl-spending').textContent  = fmt(spending);\n  document.getElementById('lbl-retadj').textContent    = (retAdj*100).toFixed(0)+'%';\n  document.getElementById('lbl-swr').textContent       = (swr*100).toFixed(2)+'%';\n  document.getElementById('lbl-geo').textContent       = GEO_NAMES[String(geo)] || '';\n\n  var rr       = realReturn(nomRet, inflation);\n  var annualInv = monthly * 12 + bonus;\n  var fn        = fireNumber(spending, retAdj, geo, swr);\n  var yrs       = yearsToFire(_fireAssets, annualInv, rr, fn);\n  var targetYear = CONFIG.START_YEAR + yrs;\n\n  document.getElementById('kpi-years').textContent    = yrs.toFixed(1) + ' yrs';\n  document.getElementById('kpi-fire-year').textContent = 'Target ' + targetYear + ' \u00b7 Age ' + (targetYear - CONFIG.BIRTH_YEAR);\n  document.getElementById('out-fire-num').textContent  = fmt(Math.round(fn));\n  document.getElementById('out-years').textContent     = yrs.toFixed(1);\n  document.getElementById('out-year').textContent      = targetYear;\n\n  for (var i = 0; i < GEO_OPTS.length; i++) {\n    var opt = GEO_OPTS[i];\n    var card = document.querySelector('.fire-loc-card[data-geo=\"'+opt.geo+'\"]');\n    if (!card) continue;\n    var fn2   = fireNumber(spending, retAdj, opt.geo, swr);\n    var y2    = yearsToFire(_fireAssets, annualInv, rr, fn2);\n    var ratio = _fireAssets / fn2;\n    card.querySelector('.fire-loc-num').textContent  = fmt(Math.round(fn2));\n    card.querySelector('.fire-loc-meta').textContent = (ratio*100).toFixed(1)+'% funded \u00b7 '+y2.toFixed(1)+' yrs';\n    card.querySelector('.fire-progress-bar').style.width = Math.min(ratio*100,100) + '%';\n  }\n\n  var proj = computeProjections(_fireAssets, annualInv, rr, fn);\n  fireChart.data.labels = proj.map(function(r){return r.year});\n  fireChart.data.datasets = [\n    { label:'Projected Assets', data:proj.map(function(r){return r.balance}), borderColor:'#22d3a5', backgroundColor:'rgba(34,211,165,.07)', fill:true, tension:0.4, pointRadius:3 },\n    { label:'FIRE Number',      data:proj.map(function(){return Math.round(fn)}), borderColor:'#f87171', borderDash:[6,4], backgroundColor:'transparent', pointRadius:0, tension:0 },\n  ];\n  fireChart.update();\n\n  var scenarios = [\n    { label:'Current plan',       extra:0 },\n    { label:'+$500/mo',           extra:500*12 },\n    { label:'+$1,000/mo',         extra:1000*12 },\n    { label:'+$2,000/mo',         extra:2000*12 },\n    { label:'+$500/mo + 2\u00d7 bonus',extra:500*12+bonus },\n  ];\n  var scenarioHtml = '';\n  for (var i = 0; i < scenarios.length; i++) {\n    var s = scenarios[i];\n    var inv2 = annualInv + s.extra;\n    var y2   = yearsToFire(_fireAssets, inv2, rr, fn);\n    var mo   = monthly + s.extra/12;\n    scenarioHtml += '<tr class=\"'+(i===0?'highlight':'')+'\">' +\n      '<td>'+s.label+'</td><td>'+fmt(mo)+'/mo</td><td>'+y2.toFixed(1)+' yrs</td>' +\n      '<td>'+(CONFIG.START_YEAR+y2)+'</td><td>Age '+(CONFIG.START_YEAR+y2-CONFIG.BIRTH_YEAR)+'</td>' +\n      '</tr>';\n  }\n  document.getElementById('scenario-tbody').innerHTML = scenarioHtml;\n\n  var swrScenarios = [\n    {name:'Very Conservative',swr:0.03},{name:'Conservative',swr:0.035},\n    {name:'Traditional (4%)',swr:0.04},{name:'Selected ('+(swr*100).toFixed(2)+'%)',swr:swr},\n  ];\n  var swrHtml = '';\n  for (var i = 0; i < swrScenarios.length; i++) {\n    var s = swrScenarios[i];\n    var fn2 = fireNumber(spending,retAdj,geo,s.swr);\n    var y2  = yearsToFire(_fireAssets,annualInv,rr,fn2);\n    swrHtml += '<tr class=\"'+(Math.abs(s.swr-swr)<.001?'highlight':'')+'\"><td>'+s.name+'</td><td>'+(s.swr*100).toFixed(2)+'%</td><td>'+fmt(Math.round(fn2))+'</td><td>'+y2.toFixed(1)+' yrs</td></tr>';\n  }\n  document.getElementById('swr-tbody').innerHTML = swrHtml;\n\n  var locHtml = '';\n  for (var i = 0; i < GEO_OPTS.length; i++) {\n    var opt = GEO_OPTS[i];\n    var fn2  = fireNumber(spending,retAdj,opt.geo,swr);\n    var need = spending*retAdj*opt.geo;\n    var y2   = yearsToFire(_fireAssets,annualInv,rr,fn2);\n    locHtml += '<tr class=\"'+(Math.abs(opt.geo-geo)<.01?'highlight':'')+'\"><td>'+opt.label+'</td><td>'+fmt(Math.round(need))+'/yr</td><td>'+fmt(Math.round(fn2))+'</td><td>'+y2.toFixed(1)+' yrs</td></tr>';\n  }\n  document.getElementById('loc-tbody').innerHTML = locHtml;\n\n  document.getElementById('kpi-fire-assets').textContent = fmt(_fireAssets);\n  var fn0 = fireNumber(spending,retAdj,geo,swr);\n  document.getElementById('kpi-fire-sub').innerHTML = (_fireAssets/fn0*100).toFixed(1)+'% of '+GEO_NAMES[String(geo)]+' target <span class=\"pill pill-yellow\">Early Stage</span>';\n}\n\nfunction syncSliders(a) {\n  if (a.nominalReturn)  { document.getElementById('sl-return').value    = (a.nominalReturn*100).toFixed(1); }\n  if (a.inflation)      { document.getElementById('sl-inflation').value = (a.inflation*100).toFixed(1); }\n  if (a.annualSpending) { document.getElementById('sl-spending').value  = a.annualSpending; }\n  if (a.retirementAdj)  { document.getElementById('sl-retadj').value    = (a.retirementAdj*100).toFixed(0); }\n  if (a.swr)            { document.getElementById('sl-swr').value       = (a.swr*100).toFixed(2); }\n  if (a.totalMonthly)   { document.getElementById('sl-monthly').value   = a.totalMonthly; }\n  if (a.bonusAmt)       { document.getElementById('sl-bonus').value     = a.bonusAmt; }\n  if (a.geoAdj) {\n    var geo = a.geoAdj;\n    var closest = [1.0,0.7,0.55].reduce(function(p,c){return Math.abs(c-geo)<Math.abs(p-geo)?c:p},1.0);\n    document.getElementById('sel-geo').value = String(closest);\n  }\n}\n\nfunction renderAllData(data) {\n  var res = renderAccounts(data.balances);\n  _fireAssets = res.fireAssets;\n\n  renderHistory(data.history);\n  renderPortfolio(data.balances.investment);\n  renderBudget(data.budget);\n  renderFireCards(_fireAssets, data.assumptions);\n\n  document.getElementById('kpi-nw').textContent = fmt(res.nw);\n  document.getElementById('note-fire-basis').textContent = 'FIRE assets = investment + savings accounts from live Tiller balances.';\n\n  if (data.assumptions.inflationAnchor) {\n    document.getElementById('note-anchor').textContent = data.assumptions.inflationAnchor;\n  }\n\n  syncSliders(data.assumptions);\n  updateModel();\n}\n\nasync function fetchLiveData() {\n  var statusEl = document.getElementById('live-status');\n  var updatedEl = document.getElementById('last-updated');\n  statusEl.textContent = '\u2b2d fetching\u2026';\n  statusEl.className = '';\n\n  try {\n    // CONFIG.GAS_URL is a relative path ('/data') served by the same\n    // Cloudflare Worker that serves this page. The Worker fetches the real\n    // Google Apps Script URL server-side (no CORS, no anti-abuse redirect \u2014\n    // that's a browser-only problem) and this is a plain same-origin fetch.\n    var res  = await fetch(CONFIG.GAS_URL);\n    var data = await res.json();\n\n    if (data.error) throw new Error(data.error);\n\n    renderAllData(data);\n    statusEl.textContent = '\u2b2d Live';\n    statusEl.className   = 'live';\n    updatedEl.textContent = 'Updated ' + new Date(data.lastUpdated).toLocaleTimeString();\n  } catch (e) {\n    statusEl.textContent = '\u2b2d Error \u2014 using cached data';\n    statusEl.className   = 'error';\n    updatedEl.textContent = e.message;\n    renderAllData(STATIC);\n  }\n}\n\ninitCharts();\nfetchLiveData();\nsetInterval(fetchLiveData, 5 * 60 * 1000);\n</script>\n</body>\n</html>\n";

export default {
  async fetch(request, env) {
    const authResponse = checkAuth(request, env);
    if (authResponse) return authResponse;

    const url = new URL(request.url);

    if (url.pathname === '/data') {
      return proxyData(env);
    }

    if (url.pathname === '/' || url.pathname === '/dashboard.html') {
      return new Response(DASHBOARD_HTML, {
        headers: { 'content-type': 'text/html; charset=UTF-8' },
      });
    }

    return new Response('Not found', { status: 404 });
  },
};

function checkAuth(request, env) {
  const unauthorized = () =>
    new Response('Authentication required', {
      status: 401,
      headers: { 'WWW-Authenticate': 'Basic realm="Financial Dashboard", charset="UTF-8"' },
    });

  const header = request.headers.get('Authorization');
  if (!header || !header.startsWith('Basic ')) return unauthorized();

  let decoded;
  try {
    decoded = atob(header.slice('Basic '.length));
  } catch (e) {
    return unauthorized();
  }

  const sepIdx = decoded.indexOf(':');
  if (sepIdx === -1) return unauthorized();

  const user = decoded.slice(0, sepIdx);
  const pass = decoded.slice(sepIdx + 1);

  if (!timingSafeEqual(user, env.AUTH_USER) || !timingSafeEqual(pass, env.AUTH_PASS)) {
    return unauthorized();
  }

  return null; // authorized
}

function timingSafeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const enc = new TextEncoder();
  const aBytes = enc.encode(a);
  const bBytes = enc.encode(b);
  if (aBytes.length !== bBytes.length) return false;
  let diff = 0;
  for (let i = 0; i < aBytes.length; i++) diff |= aBytes[i] ^ bBytes[i];
  return diff === 0;
}

async function proxyData(env) {
  try {
    const res = await fetch(env.GAS_URL, { redirect: 'follow' });
    const body = await res.text();
    return new Response(body, {
      status: res.status,
      headers: { 'content-type': 'application/json' },
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: 'Proxy fetch failed: ' + e.message }), {
      status: 502,
      headers: { 'content-type': 'application/json' },
    });
  }
}
